import torch
from torch import nn
class Model(nn.Module):
    def __init__(self):
        super().__init__()
        self.a = nn.ReLU(  # preserve constructor formatting
        )
        self.shared = self.a
    def forward(self, h):
        a = self.a(h + 1)
        return self.shared(a + a)

